import{_ as n}from"./chunks/panel-workspace.DX1HrCAW.js";import{_ as r,a as i,b as s,c as d}from"./chunks/theme-dark.CHvwPSly.js";import{_ as l,C as h,o as p,c as g,a2 as a,j as c,a as t,E as m}from"./chunks/framework.Dx-TCpNt.js";const P=JSON.parse('{"title":"Introduction","description":"KomaYomi（格读） is a local-first web app for reading manga in more than one language at once. The usual setup is three windows — the original, a translation…","frontmatter":{"description":"KomaYomi（格读） is a local-first web app for reading manga in more than one language at once. The usual setup is three windows — the original, a translation…"},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md","lastUpdated":1794842635000}'),u={name:"guide/introduction.md"};function f(b,e,w,y,v,k){const o=h("Badge");return p(),g("div",null,[e[2]||(e[2]=a('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>KomaYomi（格读） is a local-first web app for reading manga in more than one language at once. The usual setup is three windows — the original, a translation and a dictionary — plus a notes app that never lines up with the page. KomaYomi splits a page into panels, lines up the same panel across Japanese, Chinese and English, and lets you pin Markdown notes and marks — TL notes, typesetting questions, vocabulary — to the exact panel and the exact spot they belong to. It is for people learning Japanese with one eye on the translation, for scanlation checks against the raw, and for anyone who wants to see how one line was handled in each edition.</p><p>It is neither a general-purpose manga reader nor a distribution platform. Everything runs on your own machine, against your own image folders.</p><p>Already installed? Jump to <a href="#the-first-ten-minutes">The first ten minutes</a>. Starting from zero? <a href="/KomaYomi-docs/guide/installation">Install &amp; Run</a> has every path — desktop build, <code>npm run dev</code>, Docker, PWA.</p><p>Author homepages: <a href="https://x.com/payayakamo" target="_blank" rel="noopener noreferrer">X · @payayakamo</a> · <a href="https://note.com/payayakamo" target="_blank" rel="noopener noreferrer">note · @payayakamo</a>. These are the author&#39;s personal pages, not a product site.</p><h2 id="the-problem-it-solves" tabindex="-1">The problem it solves <a class="header-anchor" href="#the-problem-it-solves" aria-label="Permalink to &quot;The problem it solves&quot;">​</a></h2><p>Translations are easiest to study panel by panel, not page by page. But three scans of the same book almost never line up: the page is shifted, the panel is cropped differently, the lettering sits somewhere else. A normal image viewer gives you one zoom level, no notes, and no way to say &quot;this balloon, in these three editions&quot;.</p><p>KomaYomi adds the missing middle layer:</p><ol><li><strong>Structure</strong> — panels are detected and stored as normalized rectangles, so your boxes survive any zoom, window size or export resolution.</li><li><strong>Alignment</strong> — each language can be nudged independently until the same panel really overlaps. Yes, finally.</li><li><strong>Notes</strong> — every remark is scoped to a page or a panel, in Markdown, with tags and sources. &quot;I&#39;ll remember it later&quot; is no longer a plan.</li></ol><h2 id="the-workflow" tabindex="-1">The workflow <a class="header-anchor" href="#the-workflow" aria-label="Permalink to &quot;The workflow&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>What you do</th><th>Page</th></tr></thead><tbody><tr><td>1</td><td>Get the scans in order: <code>raw/&lt;volume&gt;/&lt;language&gt;/&lt;chapter&gt;/01.jpg</code>, or point the app at a folder you already have.</td><td><a href="/KomaYomi-docs/guide/preprocess">Preparing &amp; Renaming Images</a>, <a href="/KomaYomi-docs/guide/gallery">Library &amp; Import</a></td></tr><tr><td>2</td><td>Open a page, let it auto-split, then fix the boxes by hand. Detection is a draft, not a verdict.</td><td><a href="/KomaYomi-docs/guide/panels">Panel Workbench</a></td></tr><tr><td>3</td><td>Read 2–3 languages side by side or in overlay, align them, mask the ones you are testing yourself on.</td><td><a href="/KomaYomi-docs/guide/compare">Compare Reader</a></td></tr><tr><td>4</td><td>Write page and panel notes with tags, sources and screenshots. TL notes very much welcome.</td><td><a href="/KomaYomi-docs/guide/notes">Notes</a></td></tr><tr><td>5</td><td>Export a study HTML, PNGs for slides, or a project package for another machine.</td><td><a href="/KomaYomi-docs/guide/export">Export</a></td></tr></tbody></table><h2 id="a-tour-of-the-screen" tabindex="-1">A tour of the screen <a class="header-anchor" href="#a-tour-of-the-screen" aria-label="Permalink to &quot;A tour of the screen&quot;">​</a></h2><figure class="shot"><img src="'+n+'" alt="Panel workbench with a manga page, detected panels, resize handles and the annotation toolbar"><figcaption>The panel workbench. Top bar: page navigation, Panels / Compare, reading order, theme, interface language, Notes and Export. Left: library. Right: notes. Middle: the page with panel boxes — where you will spend most of your time.</figcaption></figure><p>The window has five regions that never move, so muscle memory can take over:</p><ul><li><strong>Top bar</strong> — brand (back to the library), volume / chapter / page, <code>‹</code> <code>›</code> page arrows, the save indicator, the <strong>Edit / Read</strong> usage mode, the <strong>Panels / Compare / Original</strong> switch, the reading-direction selector, focus mode (<code>⛶</code>), help (<code>?</code>), settings (<code>⚙</code>, edit mode only), about (<code>ⓘ</code>), the UI theme, the interface language, <strong>Notes</strong> and <strong>Export</strong>.</li><li><strong>Library sidebar</strong> (<code>S</code>) — volumes → chapters → pages, with per-page warnings and the entry points for adding a manga, folder rules, project files, exchange files and backup.</li><li><strong>Stage</strong> — the panel workbench, the compare reader or the original-page view, depending on the view switch.</li><li><strong>Notes column</strong> (<code>N</code>) — page notes, panel notes, overview search and the scratchpad.</li><li><strong>Pane splitters</strong> — drag the vertical handle between library and stage, or between stage and notes, to resize; double-click to reset.</li></ul><p>A page can carry any number of languages. The language chips in the compare reader are enabled only for languages that exist on the current page.</p><p>When the window gets narrow, the top bar and the panel-workbench toolbar do not squeeze: secondary actions fold into a <code>≡</code> overflow menu, and at phone widths only essentials such as page turning and the view switch stay visible. The menu contains exactly the same entries as the wide layout, so nothing disappears.</p><h2 id="the-start-screen" tabindex="-1">The start screen <a class="header-anchor" href="#the-start-screen" aria-label="Permalink to &quot;The start screen&quot;">​</a></h2><p>Before a library is open, the app shows a start screen. It offers four entries — <strong>Import images / Scan a folder</strong>, <strong>New library</strong>, <strong>Open a <code>.mnproj</code></strong>, and <strong>Guide</strong> — and lays the six first-run steps out as cards: import the scans, create a library or open a project, pick a page, split panels, compare languages, then annotate and export.</p><p>The cards use three columns on wide windows, two at medium widths and a single column on narrow screens. In read-only mode the import and new-library entries are hidden, leaving the project and guide entries.</p><h2 id="edit-mode-and-read-mode" tabindex="-1">Edit mode and read mode <a class="header-anchor" href="#edit-mode-and-read-mode" aria-label="Permalink to &quot;Edit mode and read mode&quot;">​</a></h2><p>The <strong>Edit / Read</strong> switch in the middle of the top bar decides whether the workspace is an authoring tool or a viewer. The choice is kept in the browser and survives reloads.</p><ul><li><strong>Edit mode</strong> — split panels, draw annotations, write notes and change the reading direction; edits are saved to <code>data/</code> according to the save mode, and the first visit to a page auto-detects its panels.</li><li><strong>Read mode</strong> — switching saves anything still pending on the current page, then clears the panel selection and closes the history and settings dialogs. A <strong>Read-only</strong> badge appears in the top bar. Useful for showing finished work to someone, or for review without accidental edits.</li></ul><p>What read mode turns off:</p><table tabindex="0"><thead><tr><th>Area</th><th>Behaviour in read mode</th></tr></thead><tbody><tr><td>Panel workbench</td><td>The split and edit toolbars, save / history, grid and templates, annotation drawing tools and keyboard nudging are hidden or inert; only zoom and pan remain.</td></tr><tr><td>Compare reader</td><td>Annotation drawing tools are hidden while existing annotations stay visible; alignment presets, anchor inputs and other controls that write data are hidden. Dragging and the wheel still pan/zoom temporarily, but nothing is written back.</td></tr><tr><td>Notes column</td><td>Viewing and searching only, with a &quot;read mode: notes are view-only&quot; notice; creating, editing, deleting and the scratchpad are unavailable.</td></tr><tr><td>Library sidebar</td><td>Adding manga, the volume settings gear, preprocessing, plugins, folder rules and backup are hidden; project files, recent pages and refresh stay.</td></tr><tr><td>Top bar and file menu</td><td>The reading-direction selector is disabled; the file menu keeps only open project, recent pages and export; <code>Ctrl+S</code> does not save.</td></tr></tbody></table><p>These limits are not just hidden buttons: while read mode is on, write requests are rejected by the server (<code>ERR_READ_ONLY</code>). Export, preview and project inspection keep working.</p><figure class="shot"><img src="'+r+'" alt="Compare reader in read mode: the top bar shows a read-only badge and the sidebar and toolbars keep only viewing actions"><figcaption>Read mode: a Read-only badge appears in the top bar and the toolbars keep only viewing actions; write requests are rejected by the server while export and preview still work.</figcaption></figure><h2 id="focus-mode" tabindex="-1">Focus mode <a class="header-anchor" href="#focus-mode" aria-label="Permalink to &quot;Focus mode&quot;">​</a></h2><p>Focus mode (the <code>⛶</code> button in the top bar, or <code>R</code>) is a different thing: it only hides the top bar, the stage toolbar, the panel section rail and the status bar so the page fills the window. It does not change the edit/read mode. Press <code>Esc</code> or <code>R</code> again to leave, or double-click empty space on touch devices. A brief tip names the exit gesture when you enter; it fades away and never sits over the artwork.</p><h2 id="the-first-ten-minutes" tabindex="-1">The first ten minutes <a class="header-anchor" href="#the-first-ten-minutes" aria-label="Permalink to &quot;The first ten minutes&quot;">​</a></h2><ol><li>Get the app running — <code>npm run dev</code> from the repo, or just launch the desktop build — then open <code>http://127.0.0.1:5173</code> in your browser.</li><li>Give the library something to read: drop a volume into <code>raw/</code>, or click <strong>＋ Add manga</strong> in the sidebar and pick a folder you already have.</li><li>Open any page from the sidebar. The first visit splits it into panels automatically and keeps the result in <code>data/pages/</code>.</li><li>To read two languages against each other, switch to <strong>Compare</strong> (<code>C</code>), tick <code>JA</code> and <code>ZH</code>, and drag one pane until the same panel lines up in both. Working panel by panel is much easier than nudging the whole page.</li><li>When something is worth keeping, open <strong>Notes</strong> (<code>N</code>), select a panel, and write your first note. <code>Ctrl+Enter</code> saves it.</li><li>Finally, press <code>E</code> to export an HTML file and open it in your browser to see how it reads.</li></ol><h2 id="what-is-implemented" tabindex="-1">What is implemented <a class="header-anchor" href="#what-is-implemented" aria-label="Permalink to &quot;What is implemented&quot;">​</a></h2><div class="status-list"><div><strong>Library</strong> — scans volumes, including several works side by side under one root, recognizes language folder aliases, pairs pages by sorted position, warns about missing pages and naming mismatches; the sidebar lists pages as two-column thumbnails, single-column thumbnails or a list with languages and note counts, remembered per browser.</div><div><strong>Panels</strong> — automatic XY-cut detection, add / move / eight-direction resize / merge / group / split / delete, manual reordering of the numbering with quick 1–10 positions and right-click move-to, percentage inputs, grid generator, panel templates, declarative layouts, plugins, cross-session page history.</div><div><strong>Annotations</strong> — arrow, rectangle, ellipse, highlighter, freehand pen, text, number badge and mosaic, optional anchor points with leader lines, page-level visibility switch, per-language isolation with a right-click menu (delete, change colour, copy to another language), PNG export support.</div><div><strong>Compare</strong> — 2–3 languages, side-by-side or overlay, per-language blur/solid masks, wheel zoom, pan, page/panel/anchor/grid alignment, saved presets, custom language order, a third original-page view with a linked/independent switch for zoom and pan, an enlarged 1:1 image viewer from the pane context menu, previous/next panel across page and chapter boundaries with auto-centring, and panel detail views with per-panel deep links. Double-click any compare row — language panes, the head or its blank margins — to open that panel; the detail view lets you drag the artwork to align it, keeps alignment for the session, and can lay panes side by side or stacked, with the language bar horizontal or vertical.</div><div><strong>Notes</strong> — page/panel notes, any number per page or panel, Markdown with a toolbar and live preview, editing an existing note in the same single editor, tags, sources, attached images, overview search, copy-for-LLM, scratchpad, pins on the artwork (a pin belongs to one language; several notes at one spot group into a counted popover), and note types: Background / Vocabulary / Reaction, one type per enabled language, and custom types kept in `data/library.json`. Typed cards share one look — a tinted surface, a 3 px colour bar and a type badge — on every surface, in both themes. The notes column runs filter → list → editor with grouping and add-by-type, and the panel detail view embeds the same editor.</div><div><strong>Export</strong> — HTML (image folder or single file), PNG (whole page, current panel, trilingual collage), share images (1080×1440 cover, single panel, language compare, long page split into strips, 18-image / 20 MB warnings), PDF via the browser print dialog, Word (`.docx`) with page images and notes and annotations baked by default, panel-border overlay, print styles, export templates.</div><div><strong>History</strong> — the operation history lists undoable edits newest first, marks the current position and jumps back to any step; it is the same undo stack, not a second one, and read-only mode shows it without allowing a jump.</div><div><strong>Modes</strong> — edit and read modes; switching to read saves first and then disables every write, and focus mode (`R`) clears the interface for immersive reading while leaving a small page/panel capsule.</div><div><strong>Storage</strong> — local folders, mounted network shares and WebDAV, with on-demand image fetching, a bounded LRU cache, scheduled automatic backups and cache management. Page writes are atomic and schema-checked, rotate `.bak` copies and take a per-page lock.</div><div><strong>Portability</strong> — `.mnproj` project packages that save back into the opened file, **Save to project file** / **Save as…** in the desktop file menu (the browser falls back to a download), `.mntpl` / `.mnexp` / `.mnpage.json` exchange files, backup and restore ZIPs, versioned schemas (page documents at 4, project manifests at 2).</div></div><h2 id="what-is-not-implemented" tabindex="-1">What is not implemented <a class="header-anchor" href="#what-is-not-implemented" aria-label="Permalink to &quot;What is not implemented&quot;">​</a></h2>',34)),c("p",null,[e[0]||(e[0]=t("These items are marked ",-1)),m(o,{type:"warning",text:"Planned"}),e[1]||(e[1]=t(" wherever they appear:",-1))]),e[3]||(e[3]=a('<ul><li>Vocabulary-list export. PDF and Word are available as <strong>PDF (print)</strong> and <strong>Word document</strong> in the export dialog.</li><li>An in-app image format converter. Renaming and splitting images are part of <a href="/KomaYomi-docs/guide/preprocess">preprocessing</a>; converting between formats still has to happen outside the app.</li><li>Broader automated integration tests for the import / export round trip.</li></ul><p>There is a separate native app, <a href="https://github.com/PayayaKamo/KomaYomi-mobile" target="_blank" rel="noopener noreferrer">KomaYomi-mobile</a>, for Android and iOS; HarmonyOS NEXT is a placeholder. It opens <code>.mnproj</code> projects, and its 0.2.1 release imports large projects by unpacking the archive natively instead of in JavaScript, so the UI no longer freezes while images are extracted.</p><figure class="shot"><img src="'+i+'" alt="Compare reader in a narrow window with the language panes stacked vertically"><figcaption>Narrow window: panes stack vertically, the library becomes a drawer. The same responsive layout the desktop app uses on a phone-sized screen.</figcaption></figure><h2 id="light-and-dark" tabindex="-1">Light and dark <a class="header-anchor" href="#light-and-dark" aria-label="Permalink to &quot;Light and dark&quot;">​</a></h2><p>The UI theme follows the system by default and can be fixed to light or dark from the top bar. The exported HTML is light-only, so screenshots and printouts stay consistent.</p><figure class="shot"><img src="'+s+'" alt="Compare reader in the light theme"><figcaption>Light theme.</figcaption></figure><figure class="shot"><img src="'+d+'" alt="Compare reader in the dark theme"><figcaption>Dark theme.</figcaption></figure><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common pitfalls&quot;">​</a></h2><ul><li><strong>Nothing appears in the library.</strong> The sidebar only scans <code>raw/</code>; add a folder or mount a remote tree first. See <a href="/KomaYomi-docs/guide/gallery">Library &amp; Import</a>.</li><li><strong>Panels are wrong on the first page.</strong> Detection is a draft, not a verdict. Fix the boxes before writing panel notes; re-running detection later discards hand edits.</li><li><strong>A language chip is greyed out.</strong> That language has no image on this page. Check page counts and the volume language mapping.</li><li><strong>Notes seem to disappear on another machine.</strong> Notes live in <code>data/</code>, images in <code>raw/</code>; move both, or export a <code>.mnproj</code>. See <a href="/KomaYomi-docs/guide/project-files">Project Files &amp; Formats</a>.</li><li><strong>An image request fails offline.</strong> Only pages that were opened before going offline are cached. See <a href="/KomaYomi-docs/guide/remote">Remote Storage &amp; Backup</a>.</li></ul><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li>New install: <a href="/KomaYomi-docs/guide/installation">Install &amp; Run</a>.</li><li>Images not ready yet: <a href="/KomaYomi-docs/guide/preprocess">Preparing &amp; Renaming Images</a>.</li><li>Ready to add images: <a href="/KomaYomi-docs/guide/gallery">Library &amp; Import</a>.</li><li>Folders have an unusual shape: <a href="/KomaYomi-docs/guide/folder-rules">Folder Detection Rules</a>.</li><li>Looking for a key: <a href="/KomaYomi-docs/guide/shortcuts">Keyboard Shortcuts</a>.</li><li>Something is wrong: <a href="/KomaYomi-docs/faq">FAQ &amp; Troubleshooting</a>.</li></ul>',11))])}const q=l(u,[["render",f]]);export{P as __pageData,q as default};
